    slug: "ip-js-006-diagnosticar-grilla-no-se-actualiza",
    title: "Diagnosticar: la grilla no refleja el cambio",
    description: "A partir del síntoma y la evidencia, identifica por qué un control PCF de dataset escribe bien pero sigue mostrando el dato viejo.",
