      context: "Un compañero conectó la tabla Solicitud TI con `pa app add data-source --connector dataverse --table sit_solicitud` y escribió la carga en una línea. Desactivó el chequeo estricto de TypeScript \"para avanzar\". `pa app run` abre la app y en la pestaña de red del navegador la petición a Dataverse responde con filas.",
