    id: "IP-ARQ-025",
    slug: "ip-arq-025-estimar-y-comprometer-en-preventa",
    title: "Estimar y comprometer en preventa",
    description: "El cliente pide precio y fecha cerrados en la primera reunión, sin Discovery y con una integración SAP sin documentar. Decide qué compromete el arquitecto y cómo.",
    type: "multiple-decision",
